-- Brazilian Invoice Loans (BIL; galacticcouncil/money-market `bil-vault`): every log the
-- explorer reads from the strategy — the BIL vault (uBIL, ERC-4626 + ERC-7540), its
-- deposit zap and the Decentral lending pool the vault invests in — for exactly the
-- topics api/src/services/bil.ts decodes, plus the HOLLAR Transfer logs between the
-- Decentral pool and anyone but the vault (its borrower's draws and repayments, which
-- no pool event states). The predicate and the select are bil.ts's BIL_LOGS_WHERE and
-- BIL_LOGS_SELECT verbatim (pinned by api/tests/bilSchema.test.ts). uBIL's own ERC-20
-- Transfer logs stay with the shared ERC-20 machinery (erc20_transfer_deltas,
-- erc20_party_transfers), and the Decentral pool's per-deposit RewardAccrued heartbeat,
-- its withdrawal requests and approvals are not read, so they are not copied.
--
-- Narrow and replay-safe like 018's juicer_logs: keyed on the raw row's own
-- (block_height, event_index) under ReplacingMergeTree(ingested_at), so a replayed raw
-- range collapses onto the same rows. `party` is the account the log names as its user —
-- a deposit's user, a redemption request's owner, a settlement's and a claim's
-- controller, an auto-claim toggle's controller, a Decentral investor or borrower, a
-- HOLLAR transfer's party other than the pool — as a lowercase H160, '' for the
-- strategy's own logs. Topics are 1-indexed: topics[1] is topic0. An upgrading database
-- gets the history from raw through the DATA_UPGRADES entry
-- (api/src/db/schemaBootstrap.ts), which replays the same predicate and select.
CREATE TABLE IF NOT EXISTS price_data.bil_logs (`block_height` UInt32, `event_index` UInt32, `extrinsic_index` Nullable(UInt32), `block_timestamp` DateTime, `contract_address` LowCardinality(String), `topic0` LowCardinality(String), `topics` Array(String), `data` String, `party` String, `ingested_at` DateTime) ENGINE = ReplacingMergeTree(ingested_at) ORDER BY (block_height, event_index) SETTINGS index_granularity = 1024;
CREATE MATERIALIZED VIEW IF NOT EXISTS price_data.bil_logs_mv TO price_data.bil_logs (`block_height` UInt32, `event_index` UInt32, `extrinsic_index` Nullable(UInt32), `block_timestamp` DateTime, `contract_address` String, `topic0` String, `topics` Array(String), `data` String, `party` String, `ingested_at` DateTime) AS SELECT block_height, event_index, extrinsic_index, block_timestamp, lower(raw_evm_logs.contract_address) AS contract_address, ifNull(raw_evm_logs.topic0, '') AS topic0, topics, data, multiIf(ifNull(raw_evm_logs.topic0, '') IN ('0x91ede45f04a37a7c170f5c1207df3b6bc748dc1e04ad5e917a241d0f52feada3', '0x93eb214b78d4914cd87b8ea2e126beb23b18c40a67418c704bf1dbc1e05af2aa', '0x4b6ced08f677a1ad8fb39b5839f2d09a3676a11641bdd563ff683b5e8edb2eaa', '0x73a19dd210f1a7f902193214c0ee91dd35ee5b4d920cba8d519eca65a7b488ca', '0x2bf878084037ba4fb4363629d72708a5bb8e8e0de5af9fe03d987d5289f6f4a2', '0x217ea3989b9d3112d2133a930216f444b7fbcaeaa4d5bc0220d099fdc928e71e', '0xac59582e5396aca512fa873a2047e7f4c80f8f55d4a06cb34a78a0187f62719f') AND length(topics) >= 2, lower(concat('0x', substring(topics[2], 27, 40))), ifNull(raw_evm_logs.topic0, '') IN ('0x1fdc681a13d8c5da54e301c7ce6542dcde4581e4725043fdab2db12ddc574506', '0x3a371cdd24458d5e2b7d414f2f40571376e0cfb7bd07effac6736e28558a189d', '0x9270c1fc51d6d3b190380df88519255073460ed60bc47c56f0cb37c3776a3dd0') AND length(topics) >= 3, lower(concat('0x', substring(topics[3], 27, 40))), ifNull(raw_evm_logs.topic0, '') = '0xfbde797d201c681b91056529119e0b02407c7bb96a4a2c75c01fc9667232c8db' AND length(topics) >= 4, lower(concat('0x', substring(topics[4], 27, 40))), ifNull(raw_evm_logs.topic0, '') = '0xddf252ad1be2c89b69c2b068fc378daa952ba7f163c4a11628f55a4df523b3ef' AND length(topics) >= 3, if(topics[2] = '0x000000000000000000000000207a626c07b73e76134177d1f44b0f32e94adb5a', lower(concat('0x', substring(topics[3], 27, 40))), lower(concat('0x', substring(topics[2], 27, 40)))), '') AS party, ingested_at FROM price_data.raw_evm_logs WHERE raw_evm_logs.topic0 IN ('0x91ede45f04a37a7c170f5c1207df3b6bc748dc1e04ad5e917a241d0f52feada3', '0x1fdc681a13d8c5da54e301c7ce6542dcde4581e4725043fdab2db12ddc574506', '0x429a07ce530fc7ce775a386bf2799667fc99df434cbef3c39dc263ad03f31c1a', '0x3a371cdd24458d5e2b7d414f2f40571376e0cfb7bd07effac6736e28558a189d', '0x9270c1fc51d6d3b190380df88519255073460ed60bc47c56f0cb37c3776a3dd0', '0xfbde797d201c681b91056529119e0b02407c7bb96a4a2c75c01fc9667232c8db', '0x61d66d8767ff702762e19c18b3cf4a23e2eef70b62fde2720244871ba6d796c7', '0x0d9763ad6ea267ddc78f78e316c8cbe385b21db691232b45a44103a0cdc2ff8f', '0xf2e373d95d66b0a34dd924c743f7c44aaf27bbef27ccaf264402dcfbdd8663e1', '0xf048617759ece50cdfd9ea84362581c37b711061101c52c6611eff62a5f3c9dc', '0x021bd3cefbdeda24b76ad254e7640f591a9e15f86d1fd4a936c99d10ad8d996a', '0xed4f44489e84da980c7e66e47d6a3449b2079b4195e282a6494db6435953037c', '0x2923cecec41b7140eaf657a035af4abb23ed61d16b1fc20a986838eb3ad99bd0', '0xdeeb69430b7153361c25d630947115165636e6a723fa8daea4b0de34b3247459', '0x823084e804e36d8971e8b86749b6b0ace7b9f87ed272bef910c1e72d123eeb48', '0x62e78cea01bee320cd4e420270b5ea74000d11b0c9f74754ebdbfc544b05a258', '0x5db9ee0a495bf2e6ff9c91a7834c1ba4fdd244a5e8aa4e537bd38aeae4b073aa', '0xae6971e30edc181eba4e21b6f0d1238924e807e69aa92f89401c1a836dd71547', '0x1dae0402eab298ec097ac31ac53541036fdec00a2ad067393523f3733b2a28da', '0x4b6ced08f677a1ad8fb39b5839f2d09a3676a11641bdd563ff683b5e8edb2eaa', '0x5d040cb5179bba6b364a85c791335d67976b938a75b6e95c0678e5618c928ed5', '0x93eb214b78d4914cd87b8ea2e126beb23b18c40a67418c704bf1dbc1e05af2aa', '0x73a19dd210f1a7f902193214c0ee91dd35ee5b4d920cba8d519eca65a7b488ca', '0x2bf878084037ba4fb4363629d72708a5bb8e8e0de5af9fe03d987d5289f6f4a2', '0x217ea3989b9d3112d2133a930216f444b7fbcaeaa4d5bc0220d099fdc928e71e', '0xac59582e5396aca512fa873a2047e7f4c80f8f55d4a06cb34a78a0187f62719f', '0xddf252ad1be2c89b69c2b068fc378daa952ba7f163c4a11628f55a4df523b3ef') AND ((lower(raw_evm_logs.contract_address) = '0x6a21891db0940491603f3cca0a9f4dba4c6e810c' AND raw_evm_logs.topic0 IN ('0x91ede45f04a37a7c170f5c1207df3b6bc748dc1e04ad5e917a241d0f52feada3', '0x1fdc681a13d8c5da54e301c7ce6542dcde4581e4725043fdab2db12ddc574506', '0x429a07ce530fc7ce775a386bf2799667fc99df434cbef3c39dc263ad03f31c1a', '0x3a371cdd24458d5e2b7d414f2f40571376e0cfb7bd07effac6736e28558a189d', '0x9270c1fc51d6d3b190380df88519255073460ed60bc47c56f0cb37c3776a3dd0', '0xfbde797d201c681b91056529119e0b02407c7bb96a4a2c75c01fc9667232c8db', '0x61d66d8767ff702762e19c18b3cf4a23e2eef70b62fde2720244871ba6d796c7', '0x0d9763ad6ea267ddc78f78e316c8cbe385b21db691232b45a44103a0cdc2ff8f', '0xf2e373d95d66b0a34dd924c743f7c44aaf27bbef27ccaf264402dcfbdd8663e1', '0xf048617759ece50cdfd9ea84362581c37b711061101c52c6611eff62a5f3c9dc', '0x021bd3cefbdeda24b76ad254e7640f591a9e15f86d1fd4a936c99d10ad8d996a', '0xed4f44489e84da980c7e66e47d6a3449b2079b4195e282a6494db6435953037c', '0x2923cecec41b7140eaf657a035af4abb23ed61d16b1fc20a986838eb3ad99bd0', '0xdeeb69430b7153361c25d630947115165636e6a723fa8daea4b0de34b3247459', '0x823084e804e36d8971e8b86749b6b0ace7b9f87ed272bef910c1e72d123eeb48', '0x62e78cea01bee320cd4e420270b5ea74000d11b0c9f74754ebdbfc544b05a258', '0x5db9ee0a495bf2e6ff9c91a7834c1ba4fdd244a5e8aa4e537bd38aeae4b073aa', '0xae6971e30edc181eba4e21b6f0d1238924e807e69aa92f89401c1a836dd71547', '0x1dae0402eab298ec097ac31ac53541036fdec00a2ad067393523f3733b2a28da', '0x4b6ced08f677a1ad8fb39b5839f2d09a3676a11641bdd563ff683b5e8edb2eaa', '0x5d040cb5179bba6b364a85c791335d67976b938a75b6e95c0678e5618c928ed5')) OR (lower(raw_evm_logs.contract_address) = '0x646fd203bbcf19b35d79f58413bb07450fdbb1db' AND raw_evm_logs.topic0 IN ('0x93eb214b78d4914cd87b8ea2e126beb23b18c40a67418c704bf1dbc1e05af2aa')) OR (lower(raw_evm_logs.contract_address) = '0x207a626c07b73e76134177d1f44b0f32e94adb5a' AND raw_evm_logs.topic0 IN ('0x73a19dd210f1a7f902193214c0ee91dd35ee5b4d920cba8d519eca65a7b488ca', '0x2bf878084037ba4fb4363629d72708a5bb8e8e0de5af9fe03d987d5289f6f4a2', '0x217ea3989b9d3112d2133a930216f444b7fbcaeaa4d5bc0220d099fdc928e71e', '0xac59582e5396aca512fa873a2047e7f4c80f8f55d4a06cb34a78a0187f62719f')) OR (lower(raw_evm_logs.contract_address) = '0x531a654d1696ed52e7275a8cede955e82620f99a' AND raw_evm_logs.topic0 = '0xddf252ad1be2c89b69c2b068fc378daa952ba7f163c4a11628f55a4df523b3ef' AND length(topics) >= 3 AND ((topics[2] = '0x000000000000000000000000207a626c07b73e76134177d1f44b0f32e94adb5a' AND topics[3] != '0x0000000000000000000000006a21891db0940491603f3cca0a9f4dba4c6e810c') OR (topics[3] = '0x000000000000000000000000207a626c07b73e76134177d1f44b0f32e94adb5a' AND topics[2] != '0x0000000000000000000000006a21891db0940491603f3cca0a9f4dba4c6e810c'))));

-- The BIL vault's exchange rate (BILVault.exchangeRate, WAD: HOLLAR per active uBIL)
-- with the assets and supply behind it, as the bil-state refresher
-- (api/src/services/bilState.ts) read them at its pinned block. A CURRENT-STATE
-- refresher snapshot (AGENTS.md, Schema and derivations): no event states the rate (each
-- position accrues by the second), so it is not reproducible from raw, and an empty table
-- refills within one refresher cadence. Every current price map prices uBIL and BIL — its
-- money market's aToken, minted 1:1 over it — by it (services/strategySharePrice.ts):
-- rate × HOLLAR's current price.
CREATE TABLE IF NOT EXISTS price_data.bil_vault_state (`vault` String, `block_height` UInt32, `exchange_rate_wad` UInt256, `total_assets` UInt256, `total_supply` UInt256, `computed_at` DateTime DEFAULT now()) ENGINE = ReplacingMergeTree(computed_at) ORDER BY vault SETTINGS index_granularity = 64;
-- The share, its underlying and the assets minted 1:1 over it (BIL, the BIL market's
-- aToken over uBIL), stated per row so the price loader reads every strategy's rate table
-- one way (services/strategySharePrice.ts). Rows written before these columns carry share
-- 0 and are skipped; the refresher rewrites the row within one cadence.
ALTER TABLE price_data.bil_vault_state ADD COLUMN IF NOT EXISTS `share_asset_id` UInt32 DEFAULT 0 AFTER `vault`;
ALTER TABLE price_data.bil_vault_state ADD COLUMN IF NOT EXISTS `collateral_asset_id` UInt32 DEFAULT 0 AFTER `share_asset_id`;
ALTER TABLE price_data.bil_vault_state ADD COLUMN IF NOT EXISTS `wrapper_asset_ids` Array(UInt32) DEFAULT [] AFTER `collateral_asset_id`;
